 "content": "def transform(grid):
    """Copy the non-background colored shape onto every matching zero-pattern occurrence."""
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v not in (0, 4, 9)}
    if len(colors) != 1:
        # ARC inputs here have one non-background marker color; conservatively leave unknowns unchanged.
        return [row[:] for row in grid]
    color = next(iter(colors))
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    min_r = min(r for r, _ in points)
    min_c = min(c for _, c in points)
    shape = [(r - min_r, c - min_c) for r, c in points]
    out = [row[:] for row in grid]
    # A matching occurrence has zero at every cell occupied by the marker shape.
    for top in range(h):
        for left in range(w):
            coords = [(top + dr, left + dc) for dr, dc in shape]
            if all(0 <= r < h and 0 <= c < w and grid[r][c] == 0 for r, c in coords):
                for r, c in coords:
                    out[r][c] = color
    return out
